#!/usr/bin/env sh
# Creates the Android platform folder from the Flutter template.
#
# `android/` is deliberately not committed: it is generated by the same Flutter
# version that builds the app, so the Gradle files cannot drift from the SDK.
# The manifest is the only file we own, and it is copied over the template.
set -eu

ROOT=$(CDPATH= cd -- "$(dirname -- "$0")/.." && pwd)
APP="$ROOT/apps/best_app"

if [ -d "$APP/android" ]; then
  echo "android/ already exists."
  exit 0
fi

TMP=$(mktemp -d)
trap 'rm -rf "$TMP"' EXIT

flutter create \
  --platforms=android \
  --org app.best \
  --project-name best_app \
  --no-pub \
  "$TMP/bootstrap" >/dev/null

cp -R "$TMP/bootstrap/android" "$APP/android"
cp "$ROOT/tool/android/AndroidManifest.xml" \
   "$APP/android/app/src/main/AndroidManifest.xml"
cp "$ROOT/tool/android/app.build.gradle.kts" \
   "$APP/android/app/build.gradle.kts"

echo "android/ created for app.best.best_app"
